mapper.update:
update bd_photo_board_mst
set delete_flg = 'Y',
    mod_dtm = current_timestamp,
    mod_id = #{actorId}
where photo_seq = #{photoSeq}
  and delete_flg = 'N'

update bd_photo_board_file_dtl
set delete_flg = 'Y',
    mod_dtm = current_timestamp,
    mod_id = #{actorId}
where photo_seq = #{photoSeq}
  and delete_flg = 'N'

update bd_photo_board_file_dtl
set delete_flg = 'Y',
    mod_dtm = current_timestamp,
    mod_id = #{actorId}
where photo_file_seq = #{photoFileSeq}
  and delete_flg = 'N'
